let inputData = $input.first().json;

// Check if the actual data is nested under a 'body' object (which happens if headers are included)
let body = inputData.body ? inputData.body : inputData;

if (!body.tenant_id || !body.message_text) {
  throw new Error('Invalid payload: Missing tenant_id or message_text');
}

// TOKEN OPTIMIZATION 1: Limit conversation history to last 10 messages
const recentHistory = (body.conversation_history || []).slice(-10);

// TOKEN OPTIMIZATION 2: Limit KB size to prevent massive token usage
const trimmedKb = (body.knowledge_base || []).map(k => {
  return `[${(k.kb_type || 'KB').toUpperCase()}] ${k.title}:\n${k.content.substring(0, 1000)}`;
});

return [{
  json: {
    ...body,
    niche: body.niche || 'general',
    conversation_history_text: recentHistory
      .map(m => `${m.sender_type === 'customer' ? 'Customer' : 'Agent'}: ${m.content}`)
      .join('\n'),
    knowledge_base_text: trimmedKb.join('\n\n'),
  }
}];

const wooOrders = $input.all().map(item => item.json).filter(o => o && o.id);
const base = $('Code Node — Validate + Unpack').first().json;

let liveContext = 'No previous orders found for this customer.';
if (wooOrders.length > 0) {
  liveContext = "Customer's recent WooCommerce orders:\n" +
    wooOrders.slice(0, 3).map(o =>
      `Order #${o.id}: ${o.status.toUpperCase()} | ` +
      `Items: ${(o.line_items || []).map(i => i.name).join(', ')} | ` +
      `Total: PKR ${o.total}`
    ).join('\n');
}

return [{ json: { ...base, live_data_context: liveContext } }];

const todayOrders = $input.first().json || [];
const base = $('Code Node — Validate + Unpack').first().json;

const liveContext = todayOrders.length > 0
  ? `Active orders today: ${todayOrders.length}\n` +
    todayOrders.map(o =>
      `• ${o.customer_name}: ${JSON.stringify(o.items)} — Status: ${o.status}`
    ).join('\n')
  : 'No active orders right now.';

return [{ json: { ...base, live_data_context: liveContext } }];

const booked = $input.first().json || [];
const base = $('Code Node — Validate + Unpack').first().json;

// Generate available slots for next 5 working days (9am–5pm, hourly)
const available = [];
for (let d = 1; d <= 7 && available.length < 8; d++) {
  const date = new Date();
  date.setDate(date.getDate() + d);
  if ([0, 6].includes(date.getDay())) continue; // skip weekends

  for (let h = 9; h <= 16; h++) {
    const dateStr = date.toISOString().split('T')[0];
    const timeStr = `${String(h).padStart(2, '0')}:00:00`;

    // Check if this slot is already taken
    const isTaken = (Array.isArray(booked) ? booked : []).some(
      b => b.appointment_date === dateStr && b.appointment_time?.startsWith(String(h).padStart(2, '0'))
    );

    if (!isTaken) {
      available.push(
        date.toLocaleDateString('en-PK', { weekday: 'short', month: 'short', day: 'numeric', timeZone: 'Asia/Karachi' }) +
        ` at ${h > 12 ? h - 12 : h}${h >= 12 ? 'pm' : 'am'}`
      );
    }
  }
}

const liveContext = available.length > 0
  ? `Available appointment slots:\n${available.slice(0, 6).join('\n')}`
  : 'No available slots found. Please call us to schedule.';

return [{ json: { ...base, live_data_context: liveContext } }];

const listings = $input.first().json || [];
const base = $('Code — Validate + Unpack').first().json;

const liveContext = listings.length > 0
  ? `Available properties:\n` + listings.map(l =>
      `• ${l.title} — PKR ${Number(l.price).toLocaleString()} | ${l.bedrooms} Bed | ${l.area} | ${l.type}`
    ).join('\n')
  : 'No listings available right now. Ask for requirements to search further.';

return [{ json: { ...base, live_data_context: liveContext } }];

const data = $input.first().json;
const msg = data.message_text.toLowerCase();
const niche = data.niche;

// Intent maps per niche
const intentMap = {
  ecommerce: [
    { intent: 'product_inquiry',    funnel: 'product_intent_detected',
      keys: ['price','cost','available','size','color','hai kya','kitna','show','catalog','fabric'] },
    { intent: 'address_provided',   funnel: 'checkout_initiated',
      keys: ['address','street','phase','block','dha','clifton','gulshan','deliver to','ghar'] },
    { intent: 'order_confirmed',    funnel: 'order_confirmed',
      keys: ['confirm','book karo','place order','proceed','haan','yes confirm','ok confirm'] },
    { intent: 'complaint',          funnel: 'refund_requested',
      keys: ['wrong','missing','damaged','return','refund','exchange','wapas','galat','nahi aaya'] },
    { intent: 'cod_request',        funnel: null,
      keys: ['cod','cash on delivery','cash pay','easypaisa','jazzcash'] },
  ],
  restaurant: [
    { intent: 'order_placement',    funnel: 'checkout_initiated',
      keys: ['order','chahiye','lena hai','send karo','deliver','takeaway','parcel'] },
    { intent: 'menu_inquiry',       funnel: 'product_intent_detected',
      keys: ['menu','price','kya hai','available','special','items','show','list'] },
    { intent: 'complaint',          funnel: null,
      keys: ['late','wrong','cold','missing','thanda','galat','complaint'] },
    { intent: 'order_confirmed',    funnel: 'order_confirmed',
      keys: ['confirm','yes','haan','theek hai','ok order','place karo'] },
  ],
  dental: [
    { intent: 'booking_intent',     funnel: 'booking_intent_detected',
      keys: ['appointment','book','slot','available','scaling','whitening','filling','root canal','checkup','consult'] },
    { intent: 'appointment_confirmed', funnel: 'appointment_confirmed',
      keys: ['confirm','yes','haan','ok book','theek hai','book kar do'] },
    { intent: 'reschedule',         funnel: null,
      keys: ['reschedule','change','postpone','badal','shift','cancel'] },
    { intent: 'clinical_query',     funnel: null,
      keys: ['pain','bleeding','dard','swollen','symptoms','infection','takleef'] },
  ],
  salon: [
    { intent: 'booking_intent',     funnel: 'booking_intent_detected',
      keys: ['appointment','book','slot','hair','facial','nails','bridal','color','cut','bleach','threading','wax'] },
    { intent: 'appointment_confirmed', funnel: 'appointment_confirmed',
      keys: ['confirm','yes','haan','ok book','theek hai'] },
    { intent: 'bridal_inquiry',     funnel: 'product_intent_detected',
      keys: ['bridal','wedding','bride','shadi','barat','nikkah','package'] },
  ],
  clinic: [
    { intent: 'booking_intent',     funnel: 'booking_intent_detected',
      keys: ['doctor','appointment','opd','consultant','specialist','book'] },
    { intent: 'appointment_confirmed', funnel: 'appointment_confirmed',
      keys: ['confirm','yes','haan','ok'] },
    { intent: 'clinical_query',     funnel: null,
      keys: ['symptoms','fever','pain','dard','cough','report','test'] },
  ],
  realestate: [
    { intent: 'property_inquiry',   funnel: 'product_intent_detected',
      keys: ['flat','house','apartment','plot','villa','office','rent','buy','purchase','sale','dha','clifton','gulshan','bahria'] },
    { intent: 'visit_request',      funnel: 'visit_requested',
      keys: ['visit','see','view','site','dekhna','saturday','sunday','kal','this week'] },
    { intent: 'requirement_provided', funnel: 'qualified',
      keys: ['budget','crore','lakh','bedroom','bed','2 bed','3 bed','area'] },
  ],
};

let detectedIntent = 'general_inquiry';
let funnelStage = null;
let requiresHumanReview = false;
let isClinicalQuery = false;

const nicheIntents = intentMap[niche] || [];
for (const { intent, funnel, keys } of nicheIntents) {
  if (keys.some(k => msg.includes(k))) {
    detectedIntent = intent;
    funnelStage = funnel;
    if (intent === 'clinical_query') {
      requiresHumanReview = true;
      isClinicalQuery = true;
    }
    if (intent === 'complaint') requiresHumanReview = true;
    break;
  }
}

// Universal human handoff detection
const humanTriggers = [
  'human', 'agent', 'real person', 'talk to someone',
  'human agent', 'manager', 'representative', 'support team',
  'koi banda', 'insaan se baat', 'banda chahiye'
];
const needsHandoff = humanTriggers.some(t => msg.includes(t));



return [{
  json: {
    ...data,
    detected_intent: detectedIntent,
    funnel_stage: funnelStage,
    requires_human_review: requiresHumanReview,
    is_clinical_query: isClinicalQuery,
    needs_human_handoff: needsHandoff,
  }
}];

const d = $input.first().json;
const nicheInstructions = {
  ecommerce:  'When taking an order, collect items and delivery address. If PREVIOUSLY EXTRACTED INFORMATION already contains the delivery address, DO NOT ask for it again. Confirm the order summary.',
  restaurant: 'When taking food orders, collect items and delivery address. If PREVIOUSLY EXTRACTED INFORMATION contains them, DO NOT ask again. Confirm the order.',
  dental:     'NEVER diagnose or prescribe. If date/time are in PREVIOUSLY EXTRACTED INFORMATION, do not ask again. Confirm appointment.',
  salon:      'When booking, confirm service, stylist, date, and time. Skip asking for details already in PREVIOUSLY EXTRACTED INFORMATION.',
  clinic:     'NEVER diagnose or prescribe. Skip asking for details already in PREVIOUSLY EXTRACTED INFORMATION.',
  realestate: 'Always qualify: ask budget, area, bedrooms. If already in PREVIOUSLY EXTRACTED INFORMATION, do not ask again.',
};

// MEMORY FIX 1: Retrieve previously extracted info so AI remembers!
const extractedInfo = d.existing_context?.context_data?.extracted_info || {};
const previousInfoText = Object.keys(extractedInfo).length > 0 
  ? JSON.stringify(extractedInfo, null, 2) 
  : 'None';

const systemPrompt = `You are ${d.agent_config.name}, an AI assistant for ${d.business_name}.

=== YOUR ROLE ===
${d.agent_config.prompt}

=== LIVE BUSINESS DATA ===
${d.live_data_context || 'No live data available.'}

=== KNOWLEDGE BASE ===
${d.knowledge_base_text || 'No knowledge base configured.'}

=== PREVIOUSLY EXTRACTED INFORMATION (CRITICAL: DO NOT ASK FOR THESE AGAIN) ===
${previousInfoText}

=== CONVERSATION HISTORY ===
${d.conversation_history_text || 'This is the start of the conversation.'}

=== NICHE-SPECIFIC INSTRUCTIONS ===
${nicheInstructions[d.niche] || 'Be helpful and professional.'}

=== RESPONSE RULES ===
- Reply in the same language the customer used (Urdu, Roman Urdu, or English)
- Keep responses concise and under 100 words to save tokens.
- Never make up information.
- If asked for a human agent, reply: "Zaroor! Main aapko abhi hamare team se connect kar raha hoon."
- Today is: ${new Date().toLocaleString('en-PK', { timeZone: 'Asia/Karachi', dateStyle: 'full' })}`;

return [{ json: { ...d, final_system_prompt: systemPrompt } }];

const inputJson = $input.first().json;

// ── 1. Extract AI reply ──
let aiReply = '';
if (typeof inputJson.output === 'string') {
    aiReply = inputJson.output;
} else if (Array.isArray(inputJson.output) && inputJson.output[0]?.content?.[0]?.text) {
    aiReply = inputJson.output[0].content[0].text;
} else if (Array.isArray(inputJson.output) && typeof inputJson.output[0]?.text === 'string') {
    aiReply = inputJson.output[0].text;
} else if (inputJson.output?.content?.[0]?.text) {
    aiReply = inputJson.output.content[0].text;
} else if (inputJson.output?.text) {
    aiReply = inputJson.output.text;
} else if (inputJson.choices?.[0]?.message?.content) {
    aiReply = inputJson.choices[0].message.content;
} else if (inputJson.message?.content) {
    aiReply = inputJson.message.content;
} else if (inputJson.text) {
    aiReply = inputJson.text;
} else if (inputJson.response?.text) {
    aiReply = inputJson.response.text;
} else {
    aiReply = 'Maafi chahta hoon, main is waqt jawab nahi de sakta. Thodi der baad dobara try karein.';
}

const d = $('System Prompt Code').first().json;
const niche = d.niche;
const msg = d.message_text || '';
const msgLower = msg.toLowerCase();
const intent = d.detected_intent;
const fullText = msg + ' ' + aiReply;
const fullLower = fullText.toLowerCase();

// ── 2. Restore previous extracted info ──
const previousInfo = d.existing_context?.context_data?.extracted_info || {};

let createRecord = false;
let recordType = null;
let recordData = { ...previousInfo };

// ═══════════════════════════════════════════════════════════════
// ECOMMERCE / RESTAURANT
// ═══════════════════════════════════════════════════════════════
if (['ecommerce', 'restaurant'].includes(niche)) {
  const orderTriggerIntents = ['order_placement', 'address_provided', 'order_confirmed', 'cod_request'];
  const hasExistingOrder = Object.keys(previousInfo).length > 0 && previousInfo.items;
  const shouldCreateOrder = orderTriggerIntents.includes(intent) ||
                            (intent === 'product_inquiry' && hasExistingOrder);

  if (shouldCreateOrder) {
    createRecord = true;
    recordType = 'order';

    // ── Item extraction (handles English, Urdu, mixed, digit-prefixed product names) ──
    let extractedItems = [];

    // Helper: clean extracted name
    const cleanName = s => s.trim().replace(/\s+/g, ' ').replace(/^(i want|mujhe|muje|mjhe|chahiye|chahie|chaie|order|please|kindly)\s+/gi, '').trim();

    // Pattern A: "5 packs of 50ml paper cups" | "3 pack of red shirts"
    const patA = /(\d+)\s*(?:pack|packs|piece|pieces|pcs|pc|item|items|x)\s+(?:of\s+)?([a-zA-Z0-9][a-zA-Z0-9\s\-\.]{2,50}?)(?=\s*(?:chaie|chahiye|chahie|order|deliver|pkr|rs|\.|,|$|\n))/gi;

    // Pattern B: item name (can start with digit like "50ml") then qty
    // "50ml paper cups 5 packs" | "paper bags 3 pack"
    const patB = /([a-zA-Z0-9][a-zA-Z0-9\s\-\.]{2,50}?)\s+(\d+)\s*(?:pack|packs|piece|pieces|pcs|pc|item|items|x)(?:\s|$|,)/gi;

    // Pattern C: "I want X Y packs" / "I need X Y packs"
    const patC = /(?:i\s+want|i\s+need|i\s+would\s+like|send\s+me|give\s+me)\s+([a-zA-Z0-9][a-zA-Z0-9\s\-\.]{1,50}?)\s+(\d+)\s*(?:pack|packs|piece|pieces|pcs|pc|item|items)/gi;

    // Pattern D: "mujhe X chaie/chahiye" (Urdu)
    const patD = /(?:mujhe|muje|mjhe|mjhay)\s+([a-zA-Z0-9][a-zA-Z0-9\s\-\.]{2,50}?)(?:\s+chaie|\s+chahiye|\s+chahie|\s+chahiyen|\s+lena|\s+order)/gi;

    // Pattern E: qty first anywhere — "5 packs paper cups"
    const patE = /(\d+)\s*(?:pack|packs|piece|pieces|pcs|pc|item|items)\s+([a-zA-Z0-9][a-zA-Z0-9\s\-\.]{2,50})(?=\s|$|,)/gi;

    // Try patterns in priority order
    const patterns = [
      [patC, 2, 1],   // "I want ITEM QTY packs"
      [patA, 1, 2],   // "QTY packs of ITEM"
      [patE, 1, 2],   // "QTY packs ITEM"
      [patB, 2, 1],   // "ITEM QTY packs"
    ];

    for (const [pat, qtyGroup, nameGroup] of patterns) {
      pat.lastIndex = 0;
      const matches = [...msg.matchAll(pat)];
      if (matches.length > 0) {
        extractedItems = matches.map(m => ({
          name: cleanName(m[nameGroup] || ''),
          qty: parseInt(m[qtyGroup]) || 1,
          price: 0,
        })).filter(i => i.name.length > 1);
        if (extractedItems.length > 0) break;
      }
    }

    // Urdu fallback (patD, qty unknown)
    if (extractedItems.length === 0) {
      patD.lastIndex = 0;
      const matches = [...msg.matchAll(patD)];
      if (matches.length > 0) {
        extractedItems = matches.map(m => ({
          name: cleanName(m[1] || ''),
          qty: 1,
          price: 0,
        })).filter(i => i.name.length > 1);
      }
    }

    // Extract price from AI reply: "PKR 850/pack" or "PKR 4,250"
    // Try unit price first
    const unitPriceMatch = aiReply.match(/(?:PKR|Rs\.?|pkr)\s*([\d,]+)\s*(?:\/pack|\/piece|\/pcs|each)/i);
    // Then total
    const totalMatch = aiReply.match(/\*{0,2}[Tt]otal\*{0,2}\s*[:\-]\s*(?:PKR|Rs\.?|pkr)\s*([\d,]+)/i);

    let unitPrice = unitPriceMatch ? parseInt(unitPriceMatch[1].replace(/,/g, '')) : 0;
    let orderTotal = totalMatch ? parseInt(totalMatch[1].replace(/,/g, '')) : 0;

    if (extractedItems.length > 0) {
      if (unitPrice > 0) extractedItems[0].price = unitPrice;
      else if (orderTotal > 0 && extractedItems[0].qty > 0) {
        extractedItems[0].price = Math.round(orderTotal / extractedItems[0].qty);
      }
    }

    // Also try to get qty from AI reply if we only got name
    if (extractedItems.length > 0 && extractedItems[0].qty === 1) {
      const aiQtyMatch = aiReply.match(/[Qq]uantity\*{0,2}\s*[:\-]\s*(\d+)/);
      if (aiQtyMatch) extractedItems[0].qty = parseInt(aiQtyMatch[1]);
    }

    // Merge items (keep previous if no new ones found)
    let currentItems = recordData.items || [];
    if (extractedItems.length > 0) {
      currentItems = extractedItems;
    }

    // ── Delivery address extraction ──
    let deliveryAddress = recordData.delivery_address || null;
    const combinedForAddr = msg + ' ' + aiReply;

    // Pattern: "Delivery Address: X" or "deliver to X"
    const addrLabelMatch = combinedForAddr.match(/(?:[Dd]elivery\s+[Aa]ddress|[Dd]eliver\s+to)\s*[:\-]?\s*([^\n,\.]{8,100})/i);
    if (addrLabelMatch && (!deliveryAddress || intent === 'address_provided')) {
      deliveryAddress = addrLabelMatch[1].trim();
    }
    // Fallback: keyword-based
    if (!deliveryAddress) {
      const addrKeywords = /\b(dha|clifton|gulshan|phase|block|street|road|avenue|lane|sector|town|garden|colony|defence|bahria|nazimabad|korangi|malir|johar|askari|highway|rd\b)/i;
      const addrMatch = combinedForAddr.match(new RegExp(`[\\w\\s,\\.\\-\\/]{0,30}${addrKeywords.source}[\\w\\s,\\.\\-\\/]{0,40}`, 'i'));
      if (addrMatch) deliveryAddress = addrMatch[0].trim();
    }

    // ── Payment method extraction ──
    let paymentMethod = recordData.payment_method || null;
    if (!paymentMethod) {
      const combined = msgLower + ' ' + aiReply.toLowerCase();
      if (/\bcod\b|cash\s+on\s+delivery/.test(combined)) paymentMethod = 'COD';
      else if (/easypaisa/.test(combined)) paymentMethod = 'Easypaisa';
      else if (/jazzcash/.test(combined)) paymentMethod = 'JazzCash';
      else if (/bank\s*transfer/.test(combined)) paymentMethod = 'Bank Transfer';
    }

    // ── Calculate total ──
    const calculatedTotal = orderTotal > 0
      ? orderTotal
      : currentItems.reduce((s, i) => s + ((i.price || 0) * (i.qty || 1)), 0);

    // ── Status logic ──
    let newStatus;
    if (intent === 'order_confirmed') {
      newStatus = 'confirmed';
    } else if (deliveryAddress && paymentMethod) {
      newStatus = 'pending';
    } else if (deliveryAddress || intent === 'address_provided') {
      newStatus = 'pending';
    } else {
      // Never downgrade a confirmed/pending order
      newStatus = ['confirmed', 'pending', 'processing'].includes(recordData.status)
        ? recordData.status
        : 'pending_address';
    }

    recordData = {
      ...recordData,
      tenant_id: d.tenant_id,
      conversation_id: d.conversation_id,
      customer_phone: d.customer_phone,
      customer_name: d.customer_name,
      niche: niche,
      items: currentItems.length > 0 ? currentItems : [{ name: 'Item from chat', qty: 1, price: 0 }],
      total_amount: calculatedTotal,   // ← renamed from 'amount' to 'total_amount'
      payment_method: paymentMethod,
      delivery_address: deliveryAddress,
      source: d.platform,
      handled_by: 'bot',
      status: newStatus,
    };

    if (intent === 'order_confirmed') {
      recordData.confirmed_at = new Date().toISOString();
    }
  }
}

// ═══════════════════════════════════════════════════════════════
// DENTAL / SALON / CLINIC
// ═══════════════════════════════════════════════════════════════
if (['dental', 'salon', 'clinic'].includes(niche)) {
  if (['booking_intent', 'appointment_confirmed'].includes(intent)) {
    createRecord = true;
    recordType = 'appointment';

    const timeMatch = (msg + ' ' + aiReply).match(/(\d{1,2})(:\d{2})?\s*(am|pm|AM|PM)/);
    const dayMatch = (msg + ' ' + aiReply).match(/(monday|tuesday|wednesday|thursday|friday|saturday|sunday|tomorrow|kal|parso)/i);

    let apptDate = recordData.appointment_date || null;
    let apptTime = recordData.appointment_time || null;

    if (dayMatch && !apptDate) {
      const dayMap = { tomorrow:1,kal:1,parso:2,monday:0,tuesday:1,wednesday:2,thursday:3,friday:4,saturday:5,sunday:6 };
      const day = dayMatch[1].toLowerCase();
      const d2 = new Date();
      if (['tomorrow','kal','parso'].includes(day)) {
        d2.setDate(d2.getDate() + (dayMap[day] || 1));
      } else {
        const target = dayMap[day]; const today = d2.getDay();
        const diff = (target - today + 7) % 7 || 7;
        d2.setDate(d2.getDate() + diff);
      }
      apptDate = d2.toISOString().split('T')[0];
    }

    if (timeMatch && !apptTime) {
      const hour = parseInt(timeMatch[1]);
      const isPM = timeMatch[3].toLowerCase() === 'pm';
      const hour24 = isPM && hour !== 12 ? hour + 12 : (!isPM && hour === 12 ? 0 : hour);
      apptTime = `${String(hour24).padStart(2,'0')}:00:00`;
    }

    recordData = {
      ...recordData,
      tenant_id: d.tenant_id,
      conversation_id: d.conversation_id,
      patient_name: d.customer_name,
      patient_phone: d.customer_phone,
      niche: niche,
      service_type: recordData.service_type || 'Consultation',
      appointment_date: apptDate,
      appointment_time: apptTime,
      status: intent === 'appointment_confirmed' ? 'confirmed' : 'pending',
      is_new_patient: !d.existing_context,
    };
  }
}

// ═══════════════════════════════════════════════════════════════
// REAL ESTATE
// ═══════════════════════════════════════════════════════════════
if (niche === 'realestate') {
  if (['property_inquiry','requirement_provided','visit_request'].includes(intent)) {
    createRecord = true;
    recordType = 'lead';

    const budgetMatch = msg.match(/(\d+\.?\d*)\s*(crore|lakh|cr|lac)/i);
    let budgetMax = recordData.budget_max || null;
    if (budgetMatch && !budgetMax) {
      const num = parseFloat(budgetMatch[1]);
      const unit = budgetMatch[2].toLowerCase();
      budgetMax = ['crore','cr'].includes(unit) ? num * 10000000 : num * 100000;
    }

    const bedMatch = msg.match(/(\d+)\s*(bed|bedroom|br)/i);
    let bedrooms = recordData.bedrooms || null;
    if (bedMatch && !bedrooms) bedrooms = parseInt(bedMatch[1]);

    recordData = {
      ...recordData,
      tenant_id: d.tenant_id,
      conversation_id: d.conversation_id,
      customer_name: d.customer_name,
      customer_phone: d.customer_phone,
      intent: recordData.intent || (msgLower.includes('rent') ? 'rent' : msgLower.includes('sell') ? 'sell' : 'buy'),
      bedrooms,
      budget_max: budgetMax,
      stage: intent === 'visit_request' ? 'visit_scheduled' :
             intent === 'requirement_provided' ? 'qualified' : (recordData.stage || 'new_inquiry'),
      temperature: 'warm',
      last_activity_at: new Date().toISOString(),
    };
  }
}

return [{
  json: {
    ...d,
    ai_reply: aiReply,
    create_record: createRecord,
    record_type: recordType,
    record_data: recordData,
  }
}];

const d = $input.first().json;
return [{
